	public class ICStocksController:BaseBusinessController
	{       
		public ICStocksController()
		{
			dal= new DALBaseProvider("ICStocks",typeof(ICStocksInfo));
		}

        public ICStocksInfo GetStockByType(String type)
        {
            String query = String.Format("SELECT * FROM ICStocks WHERE AAStatus <> 'Delete' AND ICStockType = '{0}'", type);
            DataSet ds = GetDataSet(query);
            if (ds.Tables.Count > 0 && ds.Tables[0].Rows.Count > 0)
            {
                ICStocksInfo objStocksInfo = (ICStocksInfo)GetObjectFromDataRow(ds.Tables[0].Rows[0]);
                return objStocksInfo;
            }
            return null;
        }
        public ICStocksInfo GetStockByTypeAndBranchID(String type, int branchID)
        {
            String query = String.Format("SELECT * FROM ICStocks WHERE AAStatus <> 'Delete' AND ICStockType = '{0}' AND FK_BRBranchID = {1}", type, branchID);
            DataSet ds = GetDataSet(query);
            if (ds.Tables.Count > 0 && ds.Tables[0].Rows.Count > 0)
            {
                ICStocksInfo objStocksInfo = (ICStocksInfo)GetObjectFromDataRow(ds.Tables[0].Rows[0]);
                return objStocksInfo;
            }
            return null;
        }

        /// <summary>
        /// Get stocks that their inventory can be seen by an user group
        /// </summary>
        /// <param name="userGroupID">User group id</param>
        /// <returns>List of stocks</returns>
        public List<ICStocksInfo> GetStocksByUserGroupID(int userGroupID)
        {
            DataSet ds = dal.GetDataSet("ICStocks_GetStocksByUserGroupID", userGroupID);
            return (List<ICStocksInfo>)GetListFromDataSet(ds);
        }

        /// <summary>
        /// Get all stocks
        /// </summary>
        /// <returns>List of all stocks</returns>
        public List<ICStocksInfo> GetAllStocks()
        {
            DataSet ds = GetAllObjects();
            return (List<ICStocksInfo>)GetListFromDataSet(ds);
        }

        public ICStocksInfo GetStockByAccountID(int accountID)
        {
            List<ICStocksInfo> list = GetAllStocks();
            foreach (ICStocksInfo obj in list)
            {
                if (obj.AAStatus == "Alive" && obj.FK_ACAccountID == accountID)
                {
                    return obj;
                    break;
                }
            }
            return null;
        }

        public List<ICStocksInfo> GetStockParent()
        {
            List<ICStocksInfo> list = GetAllStocks();
            list = list.Where(p => p.ICStockParentID == 0 && p.AAStatus == "Alive" && (p.ICStockType == StockType.Central.ToString() || p.ICStockType == StockType.Sale.ToString())).ToList();
            return list;
        }

        public ICStocksInfo GetStockByAccountIDAndParentID(List<ICProductAccountsInfo> accountList, int parentID)
        {
            List<ICStocksInfo> list = GetAllStocks();
            list = list.Where(p => p.ICStockParentID == parentID).ToList();
            foreach (ICStocksInfo obj in list)
            {
                if (obj.AAStatus == "Alive")
                {
                    foreach (ICProductAccountsInfo item in accountList)
                    {
                        if (item.FK_ACAccountID == obj.FK_ACAccountID)
                        {
                            return obj;
                            break;
                        }
                    }
                }
            }
            return null;
        }

        public List<ICStocksInfo> GetListStockByType(String type)
        {
            String query = String.Format("SELECT * FROM ICStocks WHERE AAStatus <> 'Delete' AND ICStockType = '{0}'", type);
            DataSet ds = GetDataSet(query);
            return (List<ICStocksInfo>)GetListFromDataSet(ds);
        }

        public override System.Collections.IList GetListFromDataSet(DataSet ds)
        {            
            List<ICStocksInfo> stocks = new List<ICStocksInfo>();
            if (ds.Tables.Count > 0)
            {
                foreach (DataRow row in ds.Tables[0].Rows)
                {
                    ICStocksInfo objStocksInfo = (ICStocksInfo)GetObjectFromDataRow(row);
                    stocks.Add(objStocksInfo);
                }
            }
            return stocks;
        }

        //DDCan [ADD] [08/06/2017] [Ordered Inventory], START
        public ICStocksInfo GetStockBySaleStockID(int stockID, string stockType)
        {
            if (stockID == 0) return new ICStocksInfo();
            ICStocksController objStocksController = new ICStocksController();
            List<ICStocksInfo> list = objStocksController.GetAllStocks();
            ICStocksInfo obj = list.Where(p => p.ICStockTemporaryParentID == stockID).FirstOrDefault();
            if (obj != null)
            {
                obj = list.Where(p => (p.ICStockParentID == obj.ICStockID &&
                                        p.ICStockType == stockType)).FirstOrDefault();
                return obj;
            }
            return null;
        }
        //DDCan [ADD] [08/06/2017] [Ordered Inventory], END
    }
    #endregion
